import hashlib

def h(x):
    return int(hashlib.md5(x.encode()).hexdigest(), 16)

class Ring:
    def __init__(self, nodes):
        self.pts = sorted((h(n), n) for n in nodes)
    def owner(self, key):
        kh = h(key)
        for tok, node in self.pts:
            if tok >= kh:
                return node
        return self.pts[0][1]

