import hashlib

N = 6
MAP_VERSION = 3

def route(key, n=N):
    return int(hashlib.md5(key.encode()).hexdigest(), 16) % n

class Client:
    def __init__(self):
        self.map_version = 0
        self.hops = 0
    def get(self, key):
        if self.map_version < MAP_VERSION:  # stale map: one extra hop to refresh
            self.hops += 1
            self.map_version = MAP_VERSION
        self.hops += 1  # direct to owning shard
        return 'shard-%d' % route(key)

c = Client()
for i in range(5):
    print('vec:%d ->' % i, c.get('vec:%d' % i))
print('total hops for 5 requests:', c.hops, '(1 refresh + 5 direct)')

import hashlib

def h(x):
    return int(hashlib.md5(x.encode()).hexdigest(), 16)

def owners(keys, nodes):
    pts = sorted((h(n), n) for n in nodes)
    out = {}
    for k in keys:
        kh = h(k)
        out[k] = next((n for t, n in pts if t >= kh), pts[0][1])
    return out

keys = ['vec:%d' % i for i in range(2000)]
old = owners(keys, ['s1', 's2', 's3'])
new = owners(keys, ['s1', 's2', 's3', 's4'])
moved = sum(1 for k in keys if old[k] != new[k])
print('keys moved when adding 4th server: %d / %d (%.1f%%)' % (moved, len(keys), 100.0 * moved / len(keys)))
print('ideal would be ~25%; consistent hashing keeps it close')

REGIONS = {'us-east': 20, 'eu-west': 90, 'ap-south': 180}  # ms from user in us-east
SHARDS = {'us-east': ['s1', 's2'], 'eu-west': ['s3'], 'ap-south': ['s4']}
HEALTHY = {'us-east': True, 'eu-west': True, 'ap-south': False}

def route(user_region):
    cands = sorted(REGIONS, key=lambda r: abs(REGIONS[r] - REGIONS[user_region]))
    for r in cands:
        if HEALTHY[r]:
            return r, SHARDS[r][0], REGIONS[r]
    raise RuntimeError('no healthy region')

for u in ['us-east', 'eu-west', 'ap-south']:
    region, shard, ms = route(u)
    print('user in %-8s -> region %-8s shard %s (%d ms)' % (u, region, shard, ms))

import random

random.seed(9)
NODES = ['n%d' % i for i in range(6)]
DEAD = {'n3'}
missed = {n: 0 for n in NODES}
state = {n: 'alive' for n in NODES}

for round_ in range(8):  # gossip rounds: everyone pings a random peer
    for n in NODES:
        if n in DEAD:
            continue
        peer = random.choice([m for m in NODES if m != n])
        if peer in DEAD:
            missed[peer] += 1
            if missed[peer] >= 3 and state[peer] == 'alive':
                state[peer] = 'suspect'
            if missed[peer] >= 5:
                state[peer] = 'dead'
    print('round %d:' % round_, {n: state[n] for n in NODES if state[n] != 'alive'} or 'all alive')
print('final: n3 is', state['n3'], '-> promote its replica, bump shard map')
